import json,base64,hashlib
from pathlib import Path
out=Path('outputs/pose_visual_20261117');same=Path('outputs/sapiens_s6_heldout_20261117');cross=Path('outputs/sapiens_unrealego_audit_20261116/validation_s5_retry');run=Path('runs/2026-11-17_pose_visual')
items=[];joints=[(5,'左肩'),(6,'右肩'),(7,'左肘'),(8,'右肘'),(62,'左腕'),(41,'右腕'),(9,'左髋'),(10,'右髋'),(11,'左膝'),(12,'右膝'),(13,'左踝'),(14,'右踝')]
for group,root,manifest,pre0,pre1 in [('同人 · S6',same,same/'manifest.json',out/'same_predictions_0.json',out/'same_predictions_1.json'),('跨人 · S5',cross,cross/'candidate_308.json',Path('outputs/fullmodel_training_20261117/results/predictions_00.json'),Path('outputs/fullmodel_training_20261117/results/predictions_01.json'))]:
 rows=json.loads(manifest.read_text())['records'];a={r['id']:r for r in json.loads(pre0.read_text())};b={r['id']:r for r in json.loads(pre1.read_text())};frames=sorted({r['frame'] for r in rows});chosen=[frames[len(frames)//4],frames[3*len(frames)//4]]
 for frame,view in zip(chosen,['left','right']):
  r=next(x for x in rows if x['frame']==frame and x['view']==view);p=root/r['image'];raw=p.read_bytes();assert hashlib.sha256(raw).hexdigest()==r['image_sha256'];gt=r['keypoints308_xy'];mask=r.get('keypoints308_candidate_in_image',r['keypoints308_supervision_mask']);x=a[r['id']]['xy'];y=b[r['id']]['xy'];pts=[]
  for j,name in joints:
   if mask[j]:pts.append(dict(name=name,gt=gt[j],original=x[j],finetuned=y[j]))
  items.append(dict(group=group,id=r['id'],frame=frame,view=view,width=r['size'][0],height=r['size'][1],image='data:image/png;base64,'+base64.b64encode(raw).decode(),points=pts))
assert len(items)==4
payload=json.dumps(items,ensure_ascii=False).replace('</','<\\/')
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>姿态检测对比</title><style>body{margin:0;background:#101722;color:#e9eff8;font:15px system-ui}main{max-width:1280px;margin:auto;padding:24px}h1{font-size:25px}p{color:#b4c3d6;line-height:1.7}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:16px 0}button{border:1px solid #506279;background:#1d2a3a;color:#fff;border-radius:8px;padding:9px 13px;cursor:pointer}button.active{background:#315a9b}label{margin-right:12px}.layout{display:grid;grid-template-columns:minmax(320px,1fr) minmax(340px,.9fr);gap:20px}canvas{width:100%;height:auto;background:black;border-radius:10px}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:8px;border-bottom:1px solid #344356;text-align:left}th{color:#9fb4ce}small{color:#a8bdd3} .legend{font-weight:700}.gt{color:#58e3ad}.orig{color:#ff8a72}.new{color:#67b7ff}@media(max-width:800px){.layout{grid-template-columns:1fr}}</style><main><h1>下视姿态检测 · 单图对比</h1><p>每张图同时显示标注投影、原始 Sapiens2-1B 与全骨干微调第 1 轮的预测。像素坐标以原图左上角为原点；点击标记可查看关节名称。</p><div id="tabs" class="toolbar"></div><div class="toolbar legend"><label class="gt"><input type="checkbox" data-key="gt" checked> ● 标注</label><label class="orig"><input type="checkbox" data-key="original" checked> × 原模型</label><label class="new"><input type="checkbox" data-key="finetuned" checked> ◆ 微调第 1 轮</label></div><p id="caption"></p><div class="layout"><div><canvas id="plot" width="872" height="872"></canvas><p id="selected">鼠标移动至标记查看关节</p></div><div><table><thead><tr><th>关节</th><th class="gt">标注 (x,y)</th><th class="orig">原模型 (x,y)</th><th class="new">微调 (x,y)</th></tr></thead><tbody id="rows"></tbody></table></div></div><p><small>仅展示有坐标且在画内的 12 个身体关节；鼻点无可靠标注。标注是关节投影，不代表可见，遮挡点精度无法仅凭图片确认。S6 是官方训练划分中留出的同人动作；S5 是官方验证划分中的跨人动作。各选两帧，左右眼各一，不能代表整体表现。</small></p></main><script>const data=__DATA__;let current=0,show={gt:true,original:true,finetuned:true};const colors={gt:'#58e3ad',original:'#ff8a72',finetuned:'#67b7ff'},cv=document.querySelector('#plot'),ctx=cv.getContext('2d'),img=new Image();function coord(p){return '('+p.map(x=>Math.round(x)).join(', ')+')'}function render(){const d=data[current];document.querySelector('#caption').textContent=d.group+' · 帧 '+d.frame+' · '+(d.view==='left'?'左眼':'右眼')+' · '+d.width+'×'+d.height;document.querySelector('#rows').innerHTML=d.points.map(p=>'<tr><td>'+p.name+'</td><td>'+coord(p.gt)+'</td><td>'+coord(p.original)+'</td><td>'+coord(p.finetuned)+'</td></tr>').join('');document.querySelectorAll('#tabs button').forEach((b,i)=>b.classList.toggle('active',i===current));cv.width=d.width;cv.height=d.height;img.onload=draw;img.src=d.image}function draw(){ctx.drawImage(img,0,0);for(const p of data[current].points){for(const key of ['gt','original','finetuned']){if(!show[key])continue;let [x,y]=p[key];ctx.strokeStyle=colors[key];ctx.fillStyle=colors[key];ctx.lineWidth=3;ctx.beginPath();if(key==='gt'){ctx.arc(x,y,6,0,2*Math.PI);ctx.fill()}else if(key==='original'){ctx.moveTo(x-7,y-7);ctx.lineTo(x+7,y+7);ctx.moveTo(x+7,y-7);ctx.lineTo(x-7,y+7);ctx.stroke()}else{ctx.moveTo(x,y-8);ctx.lineTo(x+8,y);ctx.lineTo(x,y+8);ctx.lineTo(x-8,y);ctx.closePath();ctx.fill()}}}}data.forEach((d,i)=>{let b=document.createElement('button');b.textContent=d.group+' · '+(i%2+1);b.onclick=()=>{current=i;render()};document.querySelector('#tabs').appendChild(b)});document.querySelectorAll('input').forEach(el=>el.onchange=()=>{show[el.dataset.key]=el.checked;draw()});cv.onmousemove=e=>{let b=cv.getBoundingClientRect(),x=(e.clientX-b.left)*cv.width/b.width,y=(e.clientY-b.top)*cv.height/b.height,best=null;for(const p of data[current].points)for(const k of Object.keys(show))if(show[k]){let q=p[k],d=Math.hypot(q[0]-x,q[1]-y);if(d<18&&(!best||d<best.d))best={d,text:p.name+' · '+({gt:'标注',original:'原模型',finetuned:'微调'})[k]+' '+coord(q)}}document.querySelector('#selected').textContent=best?best.text:'鼠标移动至标记查看关节'};render();</script></html>'''.replace('__DATA__',payload)
(out/'index.html').write_text(html);(run/'evidence/build.json').write_text(json.dumps({'command':'python code/build.py','exit_status':0,'selection':'each group, quartile and three-quarter frames; first left second right','samples':[{'group':x['group'],'id':x['id'],'frame':x['frame'],'view':x['view'],'points':len(x['points'])} for x in items],'local_only':True,'image_hashes_checked':True,'data_publication':False},indent=2,ensure_ascii=False)+'\n');print('built',len(items))
